// 1. Obtener la fecha de hoy en formato DD/M/AAAA o D/M/AAAA
const hoy = new Date();
const dia = hoy.getDate();
const mes = hoy.getMonth() + 1; // Los meses van de 0 a 11
const anio = hoy.getFullYear();
const fechaHoy = `${dia}/${mes}/${anio}`;

// 2. Filtrar los 104 partidos
return items.filter(partido => {
  // Leemos la columna FECHA de tu nueva tabla
  const fechaPartido = partido.json["FECHA"] ? partido.json["FECHA"].toString().trim() : "";

  // Comparamos si coincide con el día de hoy
  return fechaPartido === fechaHoy;
});

// 1. Obtenemos los datos que vienen del nodo anterior
const item = $json;

// 2. Copiamos el objeto original
let cleanJson = { ...item };

// 3. Modificamos el campo 'mensaje' de forma segura
if (cleanJson.mensaje && typeof cleanJson.mensaje === 'string') {
  cleanJson.mensaje = cleanJson.mensaje
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .replace(/\b\w/g, c => c.toUpperCase());
} else {
  // Si el mensaje no existe o está vacío, le asignamos un texto por defecto para que no falle
  cleanJson.mensaje = "Sin descripción o análisis disponible.";
}

// 4. Devolvemos el JSON limpio
return { json: cleanJson };

